export const DIALOGUES={orysia:[{prompt:'Чому Оберіг розбився?',answer:'Його тримали не камені, а пам’ять людей. Коли стежки між поселеннями спорожніли, світло перестало повертатися. Ми відновлюємо не річ — зв’язок між тими, хто ще пам’ятає.'},{prompt:'Що робити спершу?',answer:'Візьми припаси зі скрині, поговори з Яриною на Росистих луках. Після перших рівнів шукай Мирослава у східній частині лісу.'}],beekeeper:[{prompt:'Тут усі істоти небезпечні?',answer:'Ні. Росинки, гриби й дракони відповідають лише на напад. Вовки й проклята варта можуть атакувати першими. Дивись позначку характеру над ціллю.'}],myroslav:[{prompt:'Як не привести ворогів у табір?',answer:'Відступи далі від їхнього лігва. Вороги не переслідують без кінця: поза межами своїх угідь вони повертаються додому.'}],solomiya:[{prompt:'Що приховує туман?',answer:'Дорогу до собору, де дзвони називали кожного зниклого на ім’я. Без пам’яті болото не відпускає навіть живих.'}],chronicler:[{prompt:'Навіщо розпалювати горно?',answer:'Руни собору були викуті в першому вогні. Лише він зігріє шлях на перевал, де досі стоїть остання варта.'}],runekeeper:[{prompt:'Чому дракони стережуть руїни?',answer:'Вони пам’ятають вогонь і не віддають його незнайомцям. Хочеш пройти мирно — тримайся дороги. Хочеш здобути луску — прийми їхню відповідь.'}],lastkeeper:[{prompt:'Що буде після маяка?',answer:'Я не обіцяю кінця Наві. Але світло знову матиме дорогу від оселі до оселі. І кожен, хто загубиться, побачить, куди повертатися.'}]};

